    for (const tMode of teamModes) {
      state.mode = tMode;
      assert(isTodoTakadaSongEnabled() === false, `isTodoTakadaSongEnabled() must return false in ${tMode}`);
    }

    // Subtest D: User Setting / Config Disable (enableTakadaBackgroundSong = false)
