    const standoffDist = Math.hypot(retreatPos.x - deity.x, retreatPos.y - deity.y);
    assert(standoffDist >= 250, `Saitama standoff retreat distance must be >= 250px (got ${standoffDist})`);

    const prevX = saitama.x;
