      target.vy = 0;
      let krHitSfxPlayed = false;
      const prevPlaySFX = audioSystem.playSFX;
      audioSystem.playSFX = (src, vol) => {
        if (src === 'attack_fleshhit' || (typeof src === 'string' && src.includes('fleshhit'))) {
          krHitSfxPlayed = true;
        }
        return prevPlaySFX?.(src, vol);
      };
