    mockCtx.resetStackDepth();
    mahoraga.draw(mockCtx, gojo);
    assert(mockCtx.getStackDepth() === 0, `Mahoraga draw during recovery settle must have 0 canvas stack depth (got ${mockCtx.getStackDepth()})`);

