  // ─────────────────────────────────────────────────────────────────────────
  // TEST 163: GOKU & VEGETA SMOOTH PUNCH KINEMATICS & ZERO-STRETCH FLOATING PIXEL FIST STANDARD (RULE 20 & GOJO STANDARD)
  // ─────────────────────────────────────────────────────────────────────────
  {
    console.log('🧪 Test 163: Goku & Vegeta Smooth Punch Kinematics & Zero-Stretch Floating Pixel Fist Standard (Rule 20 & Gojo Standard)...');

    const { GokuFighter } = await import('../js/entities/fighters/GokuFighter.js');
    const { VegetaFighter } = await import('../js/entities/fighters/VegetaFighter.js');
    const { drawGokuSkin, drawGokuArmLinkage, drawGokuFist } = await import('../js/graphics/fighters/gokuSkin.js');
    const { drawVegetaSkin, drawVegetaArmLinkage, drawVegetaFist } = await import('../js/graphics/fighters/vegetaSkin.js');

    // 1. Verify export of arm linkage functions (strictly no-op stubs to prevent stretching arm tubes)
    assert(typeof drawGokuArmLinkage === 'function', 'drawGokuArmLinkage must be an exported function');
    assert(typeof drawVegetaArmLinkage === 'function', 'drawVegetaArmLinkage must be an exported function');

    // 2. Mock Canvas Context with transform stack depth tracker
    let stackDepth = 0;
    const drawnPaths = [];
    const mockCtx = {
      save() { stackDepth++; },
      restore() { stackDepth--; },
      translate() {},
      rotate() {},
      scale() {},
      beginPath() { drawnPaths.push('beginPath'); },
      closePath() { drawnPaths.push('closePath'); },
      moveTo(x, y) { drawnPaths.push(`moveTo(${x},${y})`); },
      lineTo(x, y) { drawnPaths.push(`lineTo(${x},${y})`); },
      stroke() { drawnPaths.push('stroke'); },
      fill() { drawnPaths.push('fill'); },
      arc(x, y, r) { drawnPaths.push(`arc(${x},${y},${r})`); },
      ellipse() {},
      drawImage() {},
      fillRect() {},
      strokeRect() {},
      clearRect() {},
      setLineDash() {},
      clip() {}
    };

    // 3. Verify Strict Prohibition of Stretching Arm Tubes (Gojo Standard):
    // Linkage functions MUST NOT mutate paths or draw rubber-band arm tubes
    const testDistances = [
      { hx: 10, hy: 8, label: 'chambered tight flexion' },
      { hx: 25, hy: 5, label: 'halfway extension' },
      { hx: 45, hy: 4, label: 'full punch reach' },
      { hx: 65, hy: 2, label: 'maximum hyper-extension' }
    ];

    for (const td of testDistances) {
      // Goku Base & Super Saiyan arm linkages (both left & right arms)
      drawGokuArmLinkage(mockCtx, 0, 10, td.hx, td.hy, 10.5, 25, true, false);
      assert(stackDepth === 0, `drawGokuArmLinkage Right (${td.label}) must maintain 0 stack depth`);
      assert(drawnPaths.length === 0, `drawGokuArmLinkage Right (${td.label}) must draw zero paths (no stretching arms)`);

      drawGokuArmLinkage(mockCtx, 0, -10, td.hx, -td.hy, 10.5, 25, false, true);
      assert(stackDepth === 0, `drawGokuArmLinkage Left SSJ (${td.label}) must maintain 0 stack depth`);
      assert(drawnPaths.length === 0, `drawGokuArmLinkage Left SSJ (${td.label}) must draw zero paths (no stretching arms)`);

      // Vegeta Base & Super Saiyan arm linkages (both left & right arms)
      drawVegetaArmLinkage(mockCtx, 0, 10, td.hx, td.hy, 10.5, 25, true, false);
      assert(stackDepth === 0, `drawVegetaArmLinkage Right (${td.label}) must maintain 0 stack depth`);
      assert(drawnPaths.length === 0, `drawVegetaArmLinkage Right (${td.label}) must draw zero paths (no stretching arms)`);

      drawVegetaArmLinkage(mockCtx, 0, -10, td.hx, -td.hy, 10.5, 25, false, true);
      assert(stackDepth === 0, `drawVegetaArmLinkage Left SSJ (${td.label}) must maintain 0 stack depth`);
      assert(drawnPaths.length === 0, `drawVegetaArmLinkage Left SSJ (${td.label}) must draw zero paths (no stretching arms)`);
    }

    // 4. Test Entity Melee Strike State & Punch Animation Execution
    const goku = new GokuFighter({ x: 200, y: 200 });
    const vegeta = new VegetaFighter({ x: 300, y: 200 });
    const dummyTarget = { x: 240, y: 200, r: 25, hp: 500, takeDamage() {}, aim() {} };

    // Initial state: not punching
    assert(goku.isPunching === false, 'Goku isPunching must start false');
    assert(vegeta.isPunching === false, 'Vegeta isPunching must start false');

    // Execute Goku Strike: triggers isPunching, sets punchAnimTimer, and cycles punch hand
    const initialGokuHand = goku.isRightPunch;
    goku._executeMeleeStrike(dummyTarget);
    assert(goku.isPunching === true, 'Goku isPunching must be true after _executeMeleeStrike');
    assert(goku.punchAnimTimer > 0, `Goku punchAnimTimer must be > 0, got ${goku.punchAnimTimer}`);
    assert(goku.isRightPunch !== initialGokuHand, 'Goku isRightPunch must alternate between strikes');

    // Verify timer decrement maintains isPunching and clears on expiry
    while (goku.punchAnimTimer > 1) {
      goku._decrementCooldowns();
      assert(goku.isPunching === true, 'Goku isPunching must remain true while punchAnimTimer > 0');
    }
    goku._decrementCooldowns();
    assert(goku.punchAnimTimer === 0, 'Goku punchAnimTimer must reach 0');
    assert(goku.isPunching === false, 'Goku isPunching must cleanly reset to false when timer expires');

    // Execute Vegeta Strike: triggers isPunching, sets punchAnimTimer, and cycles punch hand
    const initialVegetaHand = vegeta.isRightPunch;
    vegeta._executeMeleeStrike(dummyTarget);
    assert(vegeta.isPunching === true, 'Vegeta isPunching must be true after _executeMeleeStrike');
    assert(vegeta.punchAnimTimer > 0, `Vegeta punchAnimTimer must be > 0, got ${vegeta.punchAnimTimer}`);
    assert(vegeta.isRightPunch !== initialVegetaHand, 'Vegeta isRightPunch must alternate between strikes');

    // Verify timer decrement maintains isPunching and clears on expiry
    while (vegeta.punchAnimTimer > 1) {
      vegeta._decrementCooldowns();
      assert(vegeta.isPunching === true, 'Vegeta isPunching must remain true while punchAnimTimer > 0');
    }
    vegeta._decrementCooldowns();
    assert(vegeta.punchAnimTimer === 0, 'Vegeta punchAnimTimer must reach 0');
    assert(vegeta.isPunching === false, 'Vegeta isPunching must cleanly reset to false when timer expires');

    // 5. Verify Goku Dragon Hammer & Kaioken Strike activate punch animation state
    goku.dragonHammerStep = 0;
    goku.dragonHammerTimer = 25; // 25 - 1 = 24, which triggers 24 % 8 === 0 hit
    goku._updateDragonHammer(dummyTarget, { x: 0, y: 0, width: 800, height: 600 });
    assert(goku.isPunching === true, 'Goku Dragon Hammer hit must activate isPunching = true');
    assert(goku.punchAnimTimer > 0, 'Goku Dragon Hammer hit must set punchAnimTimer > 0');

    goku.startKaiokenStrike(dummyTarget);
    assert(goku.isPunching === true, 'Goku Kaioken strike must activate isPunching = true');
    assert(goku.punchAnimTimer > 0, 'Goku Kaioken strike must set punchAnimTimer > 0');

    // 6. Test Skin Rendering across 4 punch phases with arm linkages & stack depth = 0
    const testProgresses = [0.05, 0.25, 0.45, 0.75, 0.95]; // Coil, Strike, Impact Lock, Retraction, Settle
    for (const prog of testProgresses) {
      goku.isPunching = true;
      goku.punchMaxTime = 14;
      goku.punchAnimTimer = Math.round(14 * (1.0 - prog));
      goku.isRightPunch = true;
      drawGokuSkin(mockCtx, goku);
      assert(stackDepth === 0, `drawGokuSkin (p=${prog}, Right) must maintain 0 canvas stack depth`);

      goku.isRightPunch = false;
      drawGokuSkin(mockCtx, goku);
      assert(stackDepth === 0, `drawGokuSkin (p=${prog}, Left) must maintain 0 canvas stack depth`);

      vegeta.isPunching = true;
      vegeta.punchMaxTime = 15;
      vegeta.punchAnimTimer = Math.round(15 * (1.0 - prog));
      vegeta.isRightPunch = true;
      drawVegetaSkin(mockCtx, vegeta);
      assert(stackDepth === 0, `drawVegetaSkin (p=${prog}, Right) must maintain 0 canvas stack depth`);

      vegeta.isRightPunch = false;
      drawVegetaSkin(mockCtx, vegeta);
      assert(stackDepth === 0, `drawVegetaSkin (p=${prog}, Left) must maintain 0 canvas stack depth`);
    }

    console.log('      ✅ Goku & Vegeta Smooth Punch Kinematics, Zero-Stretch Floating Pixel Fists, Impact Lock & Stack Balance verified cleanly.');
  }

  // ─────────────────────────────────────────────────────────────────────────
  // TEST 164: SANS HAND TELEKINESIS STASIS PREVENTION & GRAVITY SLAM AUTO-RESET STANDARD (RULE 20)
  // ─────────────────────────────────────────────────────────────────────────
  {
    console.log('🧪 Test 164: Sans Hand Telekinesis Stasis Prevention & Gravity Slam Auto-Reset Standard (Rule 20)...');

    const { SansFighter } = await import('../js/entities/fighters/SansFighter.js');
    const { drawSansSkin } = await import('../js/graphics/fighters/sansSkin.js');

    const sans = new SansFighter({ name: 'SANS' });
    const opponent = {
      name: 'Dummy',
      x: 350,
      y: 300,
      r: 25,
      hp: 100,
      maxHp: 100,
      vx: 0,
      vy: 0,
      takeDamage(amount) { this.hp = Math.max(0, this.hp - amount); },
      aim() {}
    };

    const mockCtx = {
      _stack: 0,
      save() { this._stack++; },
      restore() { this._stack--; },
      translate() {},
      rotate() {},
      scale() {},
      beginPath() {},
      closePath() {},
      moveTo() {},
      lineTo() {},
      stroke() {},
      fill() {},
      arc() {},
      rect() {},
      fillRect() {},
      strokeRect() {},
      clearRect() {},
      drawImage() {},
      setLineDash() {},
      quadraticCurveTo() {},
      createRadialGradient() {
        return { addColorStop() {} };
      },
      clip() {},
      roundRect() {},
      createLinearGradient() { return { addColorStop() {} }; },
      createRadialGradient() { return { addColorStop() {} }; },
      getStackDepth() { return this._stack; },
      resetStackDepth() { this._stack = 0; }
    };

    // 1. Initial State: Gravity Slam inactive, hand resting at canonical default coordinates
    assert(sans.gravitySlamTimer === 0, 'Sans gravitySlamTimer must initialize at 0');
    assert(sans.blueSoulActive === false, 'Sans blueSoulActive must initialize at false');
    assert(sans.blueSoulVictim === null, 'Sans blueSoulVictim must initialize at null');

    // 2. Cast Bad Time Gravity Slam
    sans.castBadTimeGravitySlam(opponent);
    assert(sans.gravitySlamTimer > 0, 'castBadTimeGravitySlam must activate gravitySlamTimer > 0');
    assert(sans.blueSoulActive === true, 'castBadTimeGravitySlam must set blueSoulActive to true');
    assert(sans.blueSoulVictim === opponent, 'castBadTimeGravitySlam must assign blueSoulVictim');

    // 3. Test Opponent Defeat Mid-Slam: Timers & telekinesis states MUST be cleanly extinguished
    opponent.hp = 0;
    opponent.isDead = true;
    sans.update(opponent, 0, state.arena);

    assert(sans.gravitySlamTimer === 0, 'gravitySlamTimer MUST cleanly reset to 0 when opponent dies mid-slam');
    assert(sans.blueSoulActive === false, 'blueSoulActive MUST cleanly reset to false when opponent dies mid-slam');
    assert(sans.blueSoulVictim === null, 'blueSoulVictim MUST be cleared to null when opponent dies mid-slam');

    // 4. Verify Sans Skin Rendering after Opponent Defeat with Win Quote ("take a break, pal.")
    mockCtx.resetStackDepth();
    drawSansSkin(mockCtx, sans);
    assert(mockCtx.getStackDepth() === 0, 'drawSansSkin must maintain 0 stack depth after victory');

    // 5. Test Interrupt Mid-Slam (CC / TimeStop / Ambush Stasis)
    opponent.hp = 100;
    opponent.isDead = false;
    sans.castBadTimeGravitySlam(opponent);
    assert(sans.gravitySlamTimer > 0, 'gravitySlamTimer must be active');
    sans.interruptAttacks();
    assert(sans.gravitySlamTimer === 0, 'interruptAttacks must reset gravitySlamTimer to 0');
    assert(sans.blueSoulActive === false, 'interruptAttacks must reset blueSoulActive to false');
    assert(sans.blueSoulVictim === null, 'interruptAttacks must clear blueSoulVictim');

    // 6. Test Sans Defeat Mid-Slam (Sans Death)
    sans.hp = 1;
    sans.stamina = 0; // Exhaust stamina so dodge does not trigger
    sans.castBadTimeGravitySlam(opponent);
    assert(sans.gravitySlamTimer > 0, 'gravitySlamTimer must be active');
    sans.takeDamage(999, opponent);
    assert(sans.gravitySlamTimer === 0, 'takeDamage resulting in death must reset gravitySlamTimer to 0');
    assert(sans.blueSoulActive === false, 'takeDamage resulting in death must reset blueSoulActive to false');
    assert(sans.blueSoulVictim === null, 'takeDamage resulting in death must clear blueSoulVictim');

    // 7. Verify Winner Reveal Safety Gate in drawSansSkin
    sans._isWinnerReveal = true;
    sans.gravitySlamTimer = 50; // Mock lingering timer
    mockCtx.resetStackDepth();
    drawSansSkin(mockCtx, sans);
    assert(mockCtx.getStackDepth() === 0, 'drawSansSkin must maintain 0 stack depth during Winner Reveal');

    console.log('      ✅ Sans Hand Telekinesis Stasis Prevention, Gravity Slam Auto-Reset & Stack Balance verified cleanly.');
  }

  // ── TEST 165: Mahito Summoned Transfigured Humans Auto-Death & Detonation Suppression on Master Death ──
  console.log('🧪 Test 165: Mahito Transfigured Humans Auto-Death & Detonation Suppression on Master Death...');
  {
    const MahitoClass = FIGHTER_CLASS_MAP.mahito;
    const GojoClass = FIGHTER_CLASS_MAP.gojo;
    assert(MahitoClass, 'Mahito class must be registered in FIGHTER_CLASS_MAP');
    assert(GojoClass, 'Gojo class must be registered in FIGHTER_CLASS_MAP');

    const testArena = state.arena || { x: 45, y: 240, width: 450, height: 450, wallWidth: 4 };
    state.arena = testArena;
    state.gameState = 'playing';
    state.roundOver = false;
    state.matchEnded = false;
    state._isWinnerRevealActive = false;

    const { updateIllusions } = await import('../js/systems/illusionSystem.js');
    const { drawIllusions } = await import('../js/graphics/renderers/EntityRenderer.js');
    const { projectileSystem } = await import('../js/systems/projectileSystem.js');

    const mahito = new MahitoClass({ radius: 25, x: 200, y: 465, hp: 300, maxHp: 300, color: '#D946EF' });
    const opponent = new GojoClass({ radius: 25, x: 300, y: 465, hp: 500, maxHp: 500, color: '#262039' });
    mahito.team = 0;
    opponent.team = 1;
    state.fighters = [mahito, opponent];
    state.illusions = [];

    // 1. Summon Transfigured Humans
    mahito.executeSoulMultiplicity(opponent);
    const summonedCount = state.illusions.filter(il => il && il.isTransfiguredHuman && il.owner === mahito).length;
    assert(summonedCount > 0, `Mahito must summon Transfigured Humans via Soul Multiplicity, got ${summonedCount}`);

    // Verify minions are active and alive
    for (const minion of state.illusions) {
      assert(minion.isTransfiguredHuman === true, 'Minion must have isTransfiguredHuman === true');
      assert(minion.hp > 0, 'Minion must start with hp > 0');
      assert(!minion.isDying, 'Minion must not be dying upon spawn');
      assert(!minion.killedByOwnerDeath, 'Minion must not have killedByOwnerDeath upon spawn');
    }

    // 2. Mahito takes lethal damage and dies
    const initialOpponentHp = opponent.hp;
    mahito.takeDamage(9999, opponent);
    assert(mahito.hp <= 0 || mahito.isDead, 'Mahito must be dead after lethal damage');

    // 3. Verify all of Mahito's active transfigured humans immediately enter death state
    for (const minion of state.illusions) {
      if (minion.isTransfiguredHuman && minion.owner === mahito) {
        assert(minion.hp === 0, 'Transfigured Human hp must be set to 0 on master death');
        assert(minion.isDying === true, 'Transfigured Human must enter isDying state on master death');
        assert(minion.killedByOwnerDeath === true, 'Transfigured Human must be marked with killedByOwnerDeath');
        assert(minion.vx === 0 && minion.vy === 0, 'Transfigured Human movement velocity must be zeroed immediately');
      }
    }

    // 4. Advance frames to let the dying swelling animation finish and trigger explosion
    for (let f = 0; f < 30; f++) {
      updateIllusions();
    }

    // 5. Verify all transfigured humans are now fully purged from state.illusions
    const remainingTransfigured = state.illusions.filter(il => il && il.isTransfiguredHuman && il.owner === mahito);
    assert(remainingTransfigured.length === 0, `All transfigured humans must be removed after death explosion, but ${remainingTransfigured.length} remained`);

    // 6. Verify opponent HP was NOT damaged by the death explosions of minions killed by owner death
    assert(opponent.hp === initialOpponentHp, `Opponent HP must be unharmed by minions dying due to Mahito defeat, expected ${initialOpponentHp} got ${opponent.hp}`);

    // 7. Verify Body Repel projectile detonation does not spawn minions when owner is dead
    const fakeBodyRepel = {
      x: 250,
      y: 465,
      angle: 0,
      owner: 0,
      ownerFighter: mahito,
      _detonated: false
    };
    projectileSystem.triggerMahitoBodyRepelSummon(fakeBodyRepel);
    const postBodyRepelCount = state.illusions.filter(il => il && il.isTransfiguredHuman && il.owner === mahito).length;
    assert(postBodyRepelCount === 0, 'Body Repel must not spawn transfigured humans after Mahito is dead');

    // 8. Test Immediate Purge mode (killTransfiguredHumans(true))
    mahito.hp = 300;
    mahito.isDead = false;
    mahito.dead = false;
    mahito._hasDied = false;
    mahito.executeSoulMultiplicity(opponent);
    assert(state.illusions.length > 0, 'Minions must spawn again for immediate purge test');
    mahito.killTransfiguredHumans(true);
    assert(state.illusions.length === 0, 'killTransfiguredHumans(true) must immediately purge all active transfigured humans');

    // 9. Canvas 2D transform stack balance verification
    const mockCtx = {
      _stack: 0,
      save() { this._stack++; },
      restore() { this._stack--; },
      translate() {},
      rotate() {},
      scale() {},
      beginPath() {},
      closePath() {},
      moveTo() {},
      lineTo() {},
      stroke() {},
      fill() {},
      arc() {},
      rect() {},
      fillRect() {},
      strokeRect() {},
      clearRect() {},
      drawImage() {},
      setLineDash() {},
      quadraticCurveTo() {},
      bezierCurveTo() {},
      ellipse() {},
      clip() {},
      roundRect() {},
      createLinearGradient() { return { addColorStop() {} }; },
      createRadialGradient() { return { addColorStop() {} }; },
      getStackDepth() { return this._stack; },
      resetStackDepth() { this._stack = 0; }
    };
    state.ctx = mockCtx;
    mockCtx.resetStackDepth();
    mahito.executeSoulMultiplicity(opponent);
    drawIllusions();
    assert(mockCtx.getStackDepth() === 0, 'drawIllusions must maintain 0 Canvas 2D stack depth');
    mahito.killTransfiguredHumans(true);

    console.log('      ✅ Mahito Transfigured Humans Auto-Death & Detonation Suppression on Master Death verified cleanly.');
  }

