        assert(knight.skill1CooldownTimer === (rkCfg.skill1Cooldown ?? 420), 'Casting Skill 1 must arm unified skill1Cooldown');
        if (knight._activeSkill1Id) seenSkill1Picks.add(knight._activeSkill1Id);
